using System;
using System.IO;
using System.Linq;
using UnityEngine;

// 2026-11-20 Suin-ro lane repaint (r47 -> r48). The NGII 2020 source lines on
// Suin-ro cross today's lanes (Kakao aerial/road view 2026-06). The facilities
// are generated by tools/suinro_lane_repaint.py from the driven NGII lanes:
// replacement masks hide the old source lines in the carriageway, and reviewed
// strokes paint dividers, a double yellow centre and edge lines. Junction boxes,
// stop lines, arrows, guides and every driving lane/permission stay unchanged.
public static class SuinroLaneRepaint {
 [Serializable] sealed class Edit {public int revision;public RoadMapFacility[] facilities;}
 const string EditPath="config/maps/edits/2026-11-20-suinro-lane-repaint.json",Prefix="r48:suinro:";
 static void Require(bool pass,string message){if(!pass)throw new InvalidOperationException("Suin-ro repaint: "+message);}
 public static void Apply(){
  string root=ProjectMapBuild.Root,token=ProjectMapStore.Fingerprint(root);
  var before=ProjectMapStore.Load(root);
  Require(before.document.revision==47,"expected map r47, found r"+before.document.revision);
  var edit=JsonUtility.FromJson<Edit>(File.ReadAllText(Path.Combine(root,EditPath)));
  Require(edit!=null&&edit.revision==48&&edit.facilities!=null&&edit.facilities.Length>100,"edit file");
  Require(edit.facilities.All(f=>f.id.StartsWith(Prefix)),"edit ids");
  var doc=before.document.Copy();
  Require(!doc.facilities.Any(f=>f.id.StartsWith(Prefix)),"repaint already applied");
  var ids=doc.facilities.Select(f=>f.id).ToHashSet();
  Require(edit.facilities.All(f=>ids.Add(f.id)),"duplicate facility id");
  Require(edit.facilities.All(f=>ReviewedCorridorPaint.IsStroke(f)||f.kind=="lanePresentation"&&f.type==ReviewedCorridorPaint.MaskType),"only reviewed strokes and masks");
  doc.facilities=doc.facilities.Concat(edit.facilities).ToArray();
  doc.revision=48;doc.projectRevision="";doc.savedAt=DateTime.UtcNow.ToString("o");
  var result=ProjectMapPackage.Create(before.baseline,doc);
  ProjectMapStore.Save(root,result,token);
  var saved=ProjectMapStore.Load(root);
  Require(saved.contentHash==result.contentHash&&saved.baselineHash==before.baselineHash&&saved.document.revision==48,"saved map identity");
  Require(saved.document.lanes.Length==before.document.lanes.Length&&JsonUtility.ToJson(new LaneList{lanes=saved.document.lanes})==JsonUtility.ToJson(new LaneList{lanes=before.document.lanes}),"driving lanes unchanged");
  Debug.Log("SUINRO_REPAINT_APPLIED "+saved.contentHash+" facilities="+edit.facilities.Length);
 }
 [Serializable] sealed class LaneList {public RoadMapLane[] lanes;}
}
